const body = $input.first().json.body || $input.first().json;

const transcript = body.transcript || body.call?.transcript || '';
const summary = body.summary || body.call?.summary || '';
const callerPhone = body.customer?.number || body.call?.customer?.number || 'Unknown';
const callId = body.call?.id || body.id || 'N/A';
const durationSecs = body.call?.endedAt && body.call?.startedAt
  ? Math.round((new Date(body.call.endedAt) - new Date(body.call.startedAt)) / 1000) : 0;
const duration = `${Math.floor(durationSecs/60)}m ${durationSecs%60}s`;

// Extract client name
let clientName = 'Unknown Client';
const nameMatch = transcript.match(/(?:my name is|I am|I'm|this is)\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)/i);
if (nameMatch) clientName = nameMatch[1];

// Med Spa services detection
const medspaServices = [
  { key: 'botox', label: 'Botox', price: 350, duration: 30 },
  { key: 'filler', label: 'Dermal Filler', price: 750, duration: 45 },
  { key: 'lip filler', label: 'Lip Filler', price: 480, duration: 45 },
  { key: 'hydrafacial', label: 'HydraFacial', price: 280, duration: 60 },
  { key: 'facial', label: 'HydraFacial', price: 280, duration: 60 },
  { key: 'chemical peel', label: 'VI Chemical Peel', price: 350, duration: 45 },
  { key: 'peel', label: 'VI Chemical Peel', price: 350, duration: 45 },
  { key: 'laser resurfacing', label: 'Laser Resurfacing', price: 650, duration: 60 },
  { key: 'laser hair', label: 'Laser Hair Removal', price: 300, duration: 60 },
  { key: 'microneedling', label: 'Microneedling', price: 380, duration: 60 },
  { key: 'prp', label: 'Microneedling + PRP', price: 580, duration: 75 },
  { key: 'rf', label: 'RF Skin Tightening', price: 420, duration: 60 },
  { key: 'consultation', label: 'Consultation', price: 0, duration: 30 },
  { key: 'membership', label: 'Membership Inquiry', price: 0, duration: 30 },
];

let serviceType = 'General Inquiry';
let servicePrice = 0;
let serviceDuration = 30;
const fullText = (transcript + ' ' + summary).toLowerCase();
for (const svc of medspaServices) {
  if (fullText.includes(svc.key)) {
    serviceType = svc.label;
    servicePrice = svc.price;
    serviceDuration = svc.duration;
    break;
  }
}

// Provider detection
let provider = 'To Be Assigned';
if (['Botox','Dermal Filler','Lip Filler'].includes(serviceType)) provider = 'Dr. Reeves';
else if (['Laser Resurfacing','Laser Hair Removal','RF Skin Tightening'].includes(serviceType)) provider = 'Dr. Chen';
else if (['HydraFacial','VI Chemical Peel','Microneedling'].includes(serviceType)) provider = 'Esthetician Maya';

// Package detection
const packageKeywords = ['membership', 'package', 'bundle', 'radiance', 'botox club', 'glow bundle'];
const packageInterest = packageKeywords.some(k => fullText.includes(k));

// VIP detection (returning client language)
const vipKeywords = ['last time', 'usually', 'my regular', 'always come', 'been before', 'returning'];
const likelyVip = vipKeywords.some(k => fullText.includes(k));

// Booking confirmed
const appointmentBooked = /(confirmed|booked|scheduled|appointment is set|see you)/i.test(transcript + summary);
const isNewClient = /(new patient|new client|first time|never been|first visit)/i.test(transcript + summary);

// Date/time
let appointmentDate = '';
let appointmentTime = '';
const dateMatch = transcript.match(/(monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tomorrow|\d{1,2}[\/\-]\d{1,2})/i);
const timeMatch = transcript.match(/(\d{1,2}(?::\d{2})?\s*(?:AM|PM|am|pm))/i);
if (dateMatch) appointmentDate = dateMatch[1];
if (timeMatch) appointmentTime = timeMatch[1];

return [{
  json: {
    callId, callerPhone, clientName, duration,
    transcript, summary: summary || 'No summary available',
    serviceType, servicePrice, serviceDuration, provider,
    packageInterest, likelyVip, appointmentBooked,
    isNewClient, appointmentDate, appointmentTime,
    callTimestamp: new Date().toISOString(),
    callDate: new Date().toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric' }),
    callTime: new Date().toLocaleTimeString('en-US', { hour:'2-digit', minute:'2-digit' })
  }
}];

