const treatment = $input.first().json.fields['Treatment'] || '';
const lowerTreatment = treatment.toLowerCase();

let prepInstructions = '';
if (lowerTreatment.includes('botox') || lowerTreatment.includes('filler') || lowerTreatment.includes('lip')) {
  prepInstructions = 'Please avoid alcohol and blood thinners (aspirin, ibuprofen) for 24 hours before. No vigorous exercise day of.';
} else if (lowerTreatment.includes('laser') || lowerTreatment.includes('resurfacing')) {
  prepInstructions = 'Avoid sun exposure and retinol for 1 week before. Arrive with clean, makeup-free skin.';
} else if (lowerTreatment.includes('peel') || lowerTreatment.includes('chemical')) {
  prepInstructions = 'Discontinue retinol 5 days before. Avoid waxing the treatment area for 2 weeks.';
} else if (lowerTreatment.includes('microneedling')) {
  prepInstructions = 'Avoid retinol and exfoliants for 5 days before. Come with clean skin, no makeup.';
} else {
  prepInstructions = 'Arrive 10 minutes early. Come with a clean, makeup-free face for best results.';
}

return [{ json: { ...($input.first().json), prepInstructions } }];

