const body = $input.first().json.body || $input.first().json;
const from = body.From || '';
const msg = (body.Body || '').trim().toUpperCase();

let action = 'UNKNOWN';
if (['YES','CONFIRM','Y','1'].includes(msg)) action = 'CONFIRM';
else if (['CANCEL','NO','N','2'].includes(msg)) action = 'CANCEL';
else if (['RESCHEDULE','CHANGE','R','3'].includes(msg)) action = 'RESCHEDULE';
else if (msg === 'MEMBER') action = 'MEMBERSHIP';

return [{ json: { phone: from, reply: msg, action } }];

const logs = $input.all().map(i => i.json.fields);

const totalCalls = logs.length;
const apptBooked = logs.filter(l => l['Appointment Booked']).length;
const newClients = logs.filter(l => l['Is New Client']).length;
const pkgInterest = logs.filter(l => l['Package Interest']).length;
const aiBookingRate = totalCalls > 0 ? Math.round((apptBooked / totalCalls) * 100) : 0;
const estimatedRevenue = logs.reduce((sum, l) => sum + (parseInt(l['Estimated Value']) || 0), 0);

const services = {};
logs.forEach(l => { const s = l['Service Requested'] || 'Unknown'; services[s] = (services[s] || 0) + 1; });
const topServices = Object.entries(services).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([s,c])=>`${s} (${c})`).join(', ');

const timeSaved = Math.round(totalCalls * 4.5);
const reportDate = new Date().toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric' });

const html = `
<div style="font-family:Georgia,serif;max-width:600px;margin:0 auto;background:#FAF8F5;border:1px solid #E8DDD6;border-radius:12px;overflow:hidden">
  <div style="background:#1C1410;padding:24px;text-align:center">
    <div style="color:#D4AF7A;font-size:1.4rem;font-style:italic;margin-bottom:4px">Lumière Med Spa</div>
    <div style="color:rgba(255,255,255,0.5);font-size:0.75rem;letter-spacing:2px">WEEKLY AI PERFORMANCE REPORT</div>
  </div>
  <div style="padding:24px">
    <p style="color:#8A7268;font-size:0.85rem">Week ending: <strong>${reportDate}</strong></p>
    <hr style="border:1px solid #E8DDD6;margin:16px 0">
    <h3 style="color:#1C1410;font-size:1.1rem;margin-bottom:12px">✦ Call Performance</h3>
    <table style="width:100%;border-collapse:collapse;font-size:0.85rem">
      <tr><td style="padding:6px 0;color:#8A7268">Total calls handled by AI</td><td style="text-align:right;font-weight:bold;color:#C9847A">${totalCalls}</td></tr>
      <tr><td style="padding:6px 0;color:#8A7268">Appointments booked</td><td style="text-align:right;font-weight:bold;color:#C9847A">${apptBooked}</td></tr>
      <tr><td style="padding:6px 0;color:#8A7268">AI booking rate</td><td style="text-align:right;font-weight:bold;color:#C9847A">${aiBookingRate}%</td></tr>
      <tr><td style="padding:6px 0;color:#8A7268">New clients acquired</td><td style="text-align:right;font-weight:bold;color:#C9847A">${newClients}</td></tr>
      <tr><td style="padding:6px 0;color:#8A7268">Package/membership interest</td><td style="text-align:right;font-weight:bold;color:#B8965A">${pkgInterest}</td></tr>
      <tr><td style="padding:6px 0;color:#8A7268">Estimated revenue generated</td><td style="text-align:right;font-weight:bold;color:#B8965A">$${estimatedRevenue.toLocaleString()}</td></tr>
      <tr><td style="padding:6px 0;color:#8A7268">Receptionist time saved</td><td style="text-align:right;font-weight:bold;color:#7A9E7E">${timeSaved} minutes</td></tr>
    </table>
    <hr style="border:1px solid #E8DDD6;margin:16px 0">
    <p style="font-size:0.82rem;color:#8A7268"><strong>Top Services:</strong> ${topServices}</p>
    <p style="font-size:0.75rem;color:#B0A098;margin-top:16px;text-align:center">— GlowAssist AI by Your Company · Powered by Claude AI</p>
  </div>
</div>`;

return [{ json: { totalCalls, apptBooked, newClients, pkgInterest, aiBookingRate, estimatedRevenue, topServices, timeSaved, html, reportDate } }];
